    /// <summary>
    /// Customer Tobacco Licence validations while creating Sales order
    /// </summary>
    /// <param name="sender">Get Table buffer</param>
    /// <param name="e"> Get Sales Table args</param>
    [
        DataEventHandler(tableStr(SalesTable), DataEventType::Inserting),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")        
    ]
    public static void SalesTable_onInserting(Common sender, DataEventArgs e)
    {
        SalesTable              salesTable = sender as SalesTable;
        CustTable               custTable = CustTable::find(salesTable.CustAccount, false);
        LogisticsAddressState   logisticsAddressState = LogisticsAddressState::find(custTable.PartyCountry, custTable.PartyState);

        if(METCustParameters::Find().ValidateTobaccoLicence
            && logisticsAddressState.METValidateTobaccoLicence)
        {
            salesTable.METTobaccoLicenceValidationRequired = NoYes::Yes;
            salesTable.METValidTobaccoLicence = NoYes::Yes;
            
            if(METCustTobaccoLicenseTable::find(custTable.AccountNum).TobaccoLicenceExpiry < salesTable.ShippingDateRequested)
            {
                salesTable.METCustTobaccoReasonCode = logisticsAddressState.METTobaccoReasonCode;
            }
        }
        else
        {
            salesTable.METTobaccoLicenceValidationRequired = NoYes::No;
            salesTable.METValidTobaccoLicence = NoYes::No;          
        }
        // MPJ_21275_BackOrders - Begin
        METCustTable metCustTable = METCustTable::find(salesTable.CustAccount);

        if (metCustTable.AllowBackOrders == NoYes::Yes && CustParameters::find().METAllowBackOrders)
        {
            salesTable.METAllowBackOrders = NoYes::Yes;
        }
        else
        {
            salesTable.METAllowBackOrders = NoYes::No;
        }
        // MPJ_21275_BackOrders - End

    }

    /// <summary>
    /// on change to the InventSiteId update the Sales unit
    /// </summary>
    /// <param name="sender">Sender</param>
    /// <param name="e">event</param>
    [FormDataFieldEventHandler(formDataFieldStr(SalesTable, InventDim, InventSiteId), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventSiteId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        InventItemSalesSetup    inventItemSalesSetup;
        FormDataSource          datasource      = sender.dataSource().formRun().dataSource(formDataSourceStr(SalesTable,SalesLine)) as FormDataSource;
        
        SalesLine               salesLine       = datasource.cursor();
        InventDim               inventDimLoc    = sender.datasource().cursor();
        InventDim               inventDimSales;
       
        //MPJ_17845_PBMSProductMDRItemSite on 04 March 2022 by Sathish - Start
        select firstonly METSalesUnit
            from inventItemSalesSetup
            where inventItemSalesSetup.ItemId == salesLine.ItemId
                exists join inventDimSales
                    where inventDimSales.inventDimId == inventItemSalesSetup.InventDimId
                        &&  inventDimSales.InventSiteId == inventDimLoc.InventSiteId;

        salesLine.SalesUnit  = inventItemSalesSetup.METSalesUnit ? inventItemSalesSetup.METSalesUnit : salesLine.SalesUnit ;
        //MPJ_17845_PBMSProductMDRItemSite - End

    }

    /// <summary>
    ///MPJ_22901_SalesOrderTypes
    ///Generates lookup from METSalesOrderTypes
    /// </summary>
    /// <param name="sender">form control</param>
    /// <param name="e">form control event args</param>
    [FormControlEventHandler(formControlStr(SalesTable, SalesTable_METSalesOrderType), FormControlEventType::Lookup)]
    public static void SalesTable_METSalesOrderType_OnLookup(FormControl sender, FormControlEventArgs e)
    {
        FormControlCancelableSuperEventArgs ce = e as FormControlCancelableSuperEventArgs;
        SysTableLookup                      sysTableLookup = SysTableLookup::newParameters(tableNum(METSalesOrderTypes), sender);
        Query                               query = new Query();

        query.addDataSource(tableNum(METSalesOrderTypes));
        sysTableLookup.addLookupfield(fieldNum(METSalesOrderTypes, SalesOrderTypeID));
        sysTableLookup.parmQuery(query);
        sysTableLookup.performFormLookup();
        ce.CancelSuperCall();
    }

    /// <summary>
    /// MPJ_26957_AllowBackOrders
    /// Activate the Sales order header level allowback order based on customer
    /// </summary>
    /// <param name="sender">Form Data source</param>
    /// <param name="e">Form data source event</param>
    [FormDataSourceEventHandler(formDataSourceStr(SalesTable, SalesTable), FormDataSourceEventType::Activated),
        SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
    public static void SalesTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        SalesTable          salesTable      = sender.cursor();
        METCustTable        metCustTable    = METCustTable::find(salesTable.CustAccount);
        METSalesOrderTypes  salesOrderTypes = METSalesOrderTypes::find(salesTable.METSalesOrderType);

        if (CustParameters::find().METAllowBackOrders == NoYes::Yes)
        {
            // If the parameter level allowback order make it Yes, under custable manually change the allowback order
            if (metCustTable.AllowBackOrders == NoYes::Yes)
            {
                sender.object(fieldNum(SalesTable, METAllowBackOrders)).enabled(true);
            }
            else 
            {
                salesTable.METAllowBackOrders = NoYes::No;
                sender.object(fieldNum(SalesTable, METAllowBackOrders)).enabled(false);
            }
            if (salesOrderTypes.BackordersAllowed == NoYes::Yes)
            {
                sender.object(fieldNum(SalesTable, METAllowBackOrders)).enabled(true);
                salesTable.METAllowBackOrders = NoYes::Yes;
            }
            else
            {
                salesTable.METAllowBackOrders = NoYes::No;
                sender.object(fieldNum(SalesTable, METAllowBackOrders)).enabled(false);
            }
        }
        else
        {
            salesTable.METAllowBackOrders = NoYes::No;
            sender.object(fieldNum(SalesTable, METAllowBackOrders)).enabled(false);
        }
    }

    /// <summary>
    /// Intialize data on the table record
    /// </summary>
    /// <param name="sender"> Table buffer</param>
    /// <param name="e"> arg </param>
    [DataEventHandler(tableStr(SalesTable), DataEventType::InitializingRecord),
        SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
    public static void SalesTable_onInitializingRecord(Common sender, DataEventArgs e)
    {
        SalesTable  SalesTable = sender as SalesTable;

        SalesTable.METSalesOrderType = METSalesOrderTypes::findDefaultType().SalesOrderTypeID;
    }

    /// <summary>
    /// Active the sales order line
    /// </summary>
    /// <param name="sender">FormDataSource</param>
    /// <param name="e">FormDataSourceEventArgs</param>
    [FormDataSourceEventHandler(formDataSourceStr(SalesTable, SalesLine), FormDataSourceEventType::Activated),
        SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
    public static void SalesLine_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
    {
        SalesLine           salesLine       = sender.cursor();

        if (CustParameters::find().METAllowBackOrders == NoYes::Yes)
        {
            if (!salesLine.ItemId)
            {
                salesLine.METAllowBackOrders = NoYes::No;
                sender.object(fieldNum(SalesLine, METAllowBackOrders)).enabled(false);
            }
        }       
    }

/// <summary>
/// Modified the ItemId
/// </summary>
/// <param name="sender">FormDataObject</param>
/// <param name="e">FormDataFieldEventArgs</param>
[FormDataFieldEventHandler(formDataFieldStr(SalesTable, SalesLine, ItemId), FormDataFieldEventType::Modified),
    SuppressBPWarningAttribute('BPParameterNotUsed', "@MET:BPParameterNotUsedMessage")]
public static void ItemId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
{
    SalesLine           salesLine       = sender.datasource().cursor(); 
    SalesTable          salesTable      = SalesTable::find(salesLine.SalesId);
    
    if (CustParameters::find().METAllowBackOrders == NoYes::Yes)
    {
        if (METSalesOrderTypes::find(salesTable.METSalesOrderType).BackordersAllowed == NoYes::Yes ||
            (METCustTable::find(salesTable.CustAccount).AllowBackOrders == NoYes::Yes && 
                METInventTable::find(salesLine.ItemId).AllowBackOrders == NoYes::Yes &&
                InventSite::find(InventDim::find(salesLine.InventDimId).InventSiteId).METAllowBackOrders == NoYes::Yes))
        {
            salesLine.METAllowBackOrders = NoYes::Yes;
            sender.datasource().object(fieldNum(SalesLine, METAllowBackOrders)).enabled(true);
        }
        else
        {
            salesLine.METAllowBackOrders = NoYes::No;
            sender.datasource().object(fieldNum(SalesLine, METAllowBackOrders)).enabled(false);
        }
        
    }
    
}
